import { Component, Input } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-reservation-confirmation',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './reservation-confirmation.component.html'
})
export class ReservationConfirmation{

  // Reçu depuis le planning quand l'utilisateur clique sur une case
  @Input() terrainId!: number;
  @Input() heureDebut!: string;
  @Input() heureFin!: string;

  typeReservation: string = 'PUBLIC';

  jour: number = 1;
  mois: number = 1;
  annee: number = 2026;

  matricule1: string = '';
  matricule2: string = '';
  matricule3: string = '';

  montant: number = 15;
  hasPaid: boolean = false;

  jours = Array.from({ length: 31 }, (_, i) => i + 1);
  moisList = Array.from({ length: 12 }, (_, i) => i + 1);
  annees = [2025, 2026, 2027];

  payer() {
    // Ici tu appelleras ton API paiement plus tard
    this.hasPaid = true;
    alert('Paiement effectué');
  }

  confirmer() {
    if (!this.hasPaid) {
      alert('Vous devez payer avant de confirmer');
      return;
    }

    const invites = [];
    if (this.typeReservation === 'PRIVATE') {
      if (this.matricule1) invites.push(this.matricule1);
      if (this.matricule2) invites.push(this.matricule2);
      if (this.matricule3) invites.push(this.matricule3);
    }

    const reservation = {
      terrainId: this.terrainId,
      date: `${this.annee}-${this.mois}-${this.jour}`,
      heureDebut: this.heureDebut,
      heureFin: this.heureFin,
      typeReservation: this.typeReservation,
      invites: invites
    };

    console.log('Réservation envoyée :', reservation);

    // Plus tard :
    // this.reservationService.createReservation(reservation).subscribe(...)
  }

  annuler() {
    console.log('Réservation annulée');
  }
}

import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';

@Component({
  selector: 'app-confirmation-reservation',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './confirmation-reservation.html'
})
export class ConfirmationReservation implements OnInit {

  terrainId = 0;
  heureDebut = '';
  heureFin = '';
  reservationDate = '';

  typeReservation: string = 'PUBLIC';

  jour = 1;
  mois = 1;
  annee = new Date().getFullYear();

  matricule1: string = '';
  matricule2: string = '';
  matricule3: string = '';

  montant = 15;
  hasPaid = false;

  jours = Array.from({ length: 31 }, (_, i) => i + 1);
  moisList = Array.from({ length: 12 }, (_, i) => i + 1);
  annees = [new Date().getFullYear(), new Date().getFullYear() + 1, new Date().getFullYear() + 2];

  constructor(private router: Router) {}

  ngOnInit(): void {
    const navigation = this.router.getCurrentNavigation();
    const state = (navigation?.extras.state || history.state) as {
      terrainId?: number;
      date?: string;
      heureDebut?: string;
      heureFin?: string;
    };

    if (!state?.date || !state?.heureDebut) {
      this.router.navigate(['/reservation']);
      return;
    }

    this.terrainId = state.terrainId ?? 0;
    this.heureDebut = state.heureDebut;
    this.heureFin = state.heureFin ?? this.heureDebut;
    this.reservationDate = state.date;

    const [year, month, day] = this.reservationDate.split('-').map(Number);
    this.annee = year;
    this.mois = month;
    this.jour = day;
  }

  payer() {
    // Ici tu appelleras ton API paiement plus tard
    this.hasPaid = true;
    alert('Paiement effectué');
  }

  confirmer() {
    if (!this.hasPaid) {
      alert('Vous devez payer avant de confirmer');
      return;
    }

    const invites = [];
    if (this.typeReservation === 'PRIVATE') {
      if (this.matricule1) invites.push(this.matricule1);
      if (this.matricule2) invites.push(this.matricule2);
      if (this.matricule3) invites.push(this.matricule3);
    }

    const reservation = {
      terrainId: this.terrainId,
      date: `${this.annee}-${this.mois}-${this.jour}`,
      heureDebut: this.heureDebut,
      heureFin: this.heureFin,
      typeReservation: this.typeReservation,
      invites: invites
    };

    console.log('Réservation envoyée :', reservation);

    // Plus tard :
    // this.reservationService.createReservation(reservation).subscribe(...)
  }

  annuler() {
    this.router.navigate(['/reservation']);
  }
}

